 commands=nil buffers=nil parents=nil parentVisible=nil poses=nil jobs=nil groups=nil dispatch=nil SET_IMAGE=nil SET_VISIBLE=nil SET_POSITION=nil SET_DIMENSIONS=nil SET_ROTATION=nil
end
